using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CondemnationTearOmenData", menuName = "Data/Battle/Omens System/Omen Data/Orion/CondemnationTearOmenData")]
public class CondemnationTearOmenData : GainSomethingWithDrawBackOmenData
{
	[Header("CondemnationTear")]
	[SerializeField]
	private OnStartOfTurnOmenData onStartOfTurnOmenData;

	public override void Initialize(OmenInstance omenInstance)
	{
		onStartOfTurnOmenData.Initialize(omenInstance);
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		onStartOfTurnOmenData.OmenRemoved();
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		return onStartOfTurnOmenData.OmenConvertedDescription() + "\n" + base.OmenConvertedDescription();
	}
}
